  const deepCaseReviewMarkup = deepCaseReview ? `<section class="card section" id="apr-deep-case-review" aria-labelledby="apr-deep-case-review-title"><p class="label">APR \xB7 revisione profonda prima dell'operatore</p><h2 id="apr-deep-case-review-title">${escapeHtml(deepCaseReview.status.toUpperCase())} \u2014 ${deepCaseReview.progress.processed}/${deepCaseReview.progress.total}</h2><div class="stats readiness-stats"><div class="stat"><strong>${deepCaseReview.progress.technicalRepair}</strong><span>riparazioni tecniche</span></div><div class="stat"><strong>${deepCaseReview.progress.operatorRequired}</strong><span>prove operatore reali</span></div><div class="stat"><strong>${deepCaseReview.progress.businessRuleRequired}</strong><span>regole business mancanti</span></div><div class="stat"><strong>${deepCaseReview.progress.autoResolved}</strong><span>risolti con regole esistenti</span></div></div><p class="reason readiness-reason">${escapeHtml(deepCaseReview.reason)}</p><p class="next"><strong>Prossima azione</strong><br>${escapeHtml(deepCaseReview.nextAction)}</p><div class="table-wrap"><table><thead><tr><th>Cliente</th><th>Modulo</th><th>Classificazione</th><th>Prove</th><th>Motivo/prossima azione</th></tr></thead><tbody>${deepCaseReview.items.map((item) => `<tr><td>${escapeHtml(item.displayName)}</td><td>${escapeHtml(item.productModule)}</td><td><span class="state-pill">${escapeHtml(item.classification ?? item.state)}</span></td><td>${escapeHtml(item.evidencePasses.map((pass) => `${pass.id}:${pass.ok ? "ok" : "no"}`).join(" \xB7 ") || "in attesa")}</td><td>${escapeHtml(item.reason)}<br><strong>${escapeHtml(item.nextAction)}</strong></td></tr>`).join("")}</tbody></table></div><p class="footer">Checkpoint r${deepCaseReview.revision} \xB7 lock ${escapeHtml(deepCaseReview.currentCustomerKey ?? "nessuno")} \xB7 externalActionAllowed=false \xB7 ultimo evento ${escapeHtml(deepCaseReview.lastEvent.type)}</p></section>` : "";
  const operatorQuestionsMarkup = operatorQuestions ? `<section class="card section" id="operator-questions" aria-labelledby="operator-questions-title"><p class="label">Richiesto intervento operatore \xB7 domande strutturate persistenti</p><h2 id="operator-questions-title">Decisioni aperte: ${operatorQuestions.openCount}</h2><p class="reason">APR mostra il dato e la fonte. La risposta risolve la pratica indicata e viene registrata separatamente come candidata a regola generale; diventa attiva soltanto dopo prova, test, matrice e bundle certificato.</p><div class="table-wrap"><table><thead><tr><th>Pratica/campo</th><th>Domanda e fonte</th><th>Risposta</th><th>Stato</th></tr></thead><tbody>${operatorQuestions.questions.length ? operatorQuestions.questions.map((question) => `<tr><td><strong>${escapeHtml(question.displayName)}</strong><span>${escapeHtml(question.field)}</span></td><td>${escapeHtml(question.prompt)}<br><small>${escapeHtml(question.evidenceText)}</small></td><td>${question.status === "open" && csrfToken ? `<form method="post" action="/operator/questions/${encodeURIComponent(question.id)}/answer"><input type="hidden" name="csrf" value="${escapeHtml(csrfToken)}">${question.kind === "missing_measurement" ? `<input name="widthValue" type="number" min="0" step="0.1" aria-label="Larghezza" placeholder="Larghezza (lascia vuoto se non disponibile)"><input name="heightValue" type="number" min="0" step="0.1" aria-label="Altezza" placeholder="Altezza (lascia vuoto se non disponibile)">` : ""}<select name="answer" aria-label="Risposta" required>${question.choices.map((choice) => `<option value="${escapeHtml(choice.value)}">${escapeHtml(choice.label)}</option>`).join("")}</select><input name="note" type="text" maxlength="500" aria-label="Nota facoltativa" placeholder="Nota facoltativa, es. misure in millimetri"><button type="submit">Registra e riaccoda</button></form>` : escapeHtml(question.answer ? `${question.answer.value} \xB7 ${question.answer.note || "nessuna nota"}` : "\u2014")}</td><td><span class="state-pill">${escapeHtml(question.status)}</span></td></tr>`).join("") : `<tr><td>\u2014</td><td>Nessuna domanda aperta.</td><td>\u2014</td><td><span class="state-pill">idle</span></td></tr>`}</tbody></table></div><p class="footer">Ultimo evento ${escapeHtml(operatorQuestions.lastEvent.type)} \xB7 checkpoint r${operatorQuestions.revision} \xB7 \u201Cnon determinabile\u201D mantiene il blocco.</p></section>` : "";
