    const selectValue = definition.fieldId === "beneficiario.nazione_nascita" ? nationIsItaly("beneficiario.nazione_nascita") ? "ita" : verifiedForeignBirth?.selectValue : definition.fieldId === "beneficiario.nazione_residenza" && nationIsItaly("beneficiario.nazione_residenza") ? "ita" : void 0;
