// src/features/enea-lab/portalCalculation.ts
function numericValue2(value) {
  const compact2 = value.trim().replace(/[^0-9,.-]/g, "");
  const normalized = compact2.includes(",") ? compact2.replace(/\./g, "").replace(",", ".") : compact2;
  const parsed = Number(normalized);
  return Number.isFinite(parsed) && parsed > 0 ? String(parsed) : "";
}
function buildEneaCalculationPortalScript(mapped) {
  const fields = mapped.sections.flatMap(({ fields: fields2 }) => fields2);
  const field = fields.find(({ id }) => id === "schermature.risparmio_energia");
  const authorized = field?.status === "ready" && field.source === "Regola controllata" && field.note?.includes("screening-energy-savings-v1");
  const value = authorized ? numericValue2(field.value) : "";
  const runtime = {
    fields: value ? [{ portalId: "id-risp", control: "input", value }] : [],
    pageName: "Calcolo costi e detrazioni",
    markerIds: ["id-risp"],
    successMessage: "ENEA Lab: risparmio energetico compilato. Nessun salvataggio o invio eseguito."
  };
  const principalHome = fields.find(({ id }) => id === "beneficiario.abitazione_principale");
  const expense = fields.find(({ id }) => id === "schermature.spesa");
  const secondaryHome = principalHome?.status === "ready" && principalHome.value.trim().toLocaleLowerCase("it") === "no";
  const expenseValue = expense?.status === "ready" && expense.source === "Calcolo ENEA" ? numericValue2(expense.value) : "";
  const allocationRuntime = secondaryHome && expenseValue ? {
    fields: [],
    pageName: "Allocazione costi e detrazioni",
    markerIds: [],
    hostRoute: "calcolo",
    expenseAllocation: {
      fieldId: "schermature.spesa",
      interventionLabel: "Schermature solari",
      value: expenseValue,
      rate: 36,
      appliedRuleIds: [USER_AUTHORIZED_RULE_IDS.secondaryHome36PercentAllocation, "system-atomic-checkpoint-resume"]
    },
    successMessage: "APR: allocazione 36% preparata; salvataggio separato, anteprima e invio vietati."
  } : null;
  return {
    script: buildEneaPortalRuntimeScript(runtime),
    readyFieldIds: [...value ? ["schermature.risparmio_energia"] : [], ...allocationRuntime ? ["schermature.spesa"] : []],
    skippedFieldIds: value ? [] : ["schermature.risparmio_energia"],
    runtime,
    allocationRuntime
  };
}

// src/features/enea-lab/portalGenerator.ts
var generatorPortalFields = (generatorLabel) => [
  { fieldId: "impianto.numero_generatori", portalId: "id-num" },
  // Il modale ENEA della riga "Pompa di calore / Impianto geotermico"
  // espone P.E.A. con id-pea al posto del rendimento id-n. La sorgente locale
  // resta il valore convenzionale TEST gia auditato; qui cambia soltanto il
  // binding al controllo osservato del portale.
  { fieldId: "impianto.rendimento", portalId: normalizeGeneratorLabel(generatorLabel) === "impianto geotermico" ? "id-pea" : "id-n" },
  { fieldId: "impianto.potenza", portalId: "id-pn" }
];
function normalizeGeneratorLabel(value) {
  return value.normalize("NFD").replace(/[\u0300-\u036f]/g, "").trim().replace(/\s+/g, " ").toLocaleLowerCase("it");
}
function numericValue3(value) {
  return value.trim().replace(/[^0-9,.-]/g, "");
}
function isValidGeneratorValue(fieldId, value) {
  const parsed = Number(value.replace(",", "."));
  if (!Number.isFinite(parsed)) return false;
  if (fieldId === "impianto.numero_generatori") return Number.isInteger(parsed) && parsed > 0;
  if (fieldId === "impianto.rendimento") return parsed > 0 && parsed <= 100;
  if (fieldId === "impianto.potenza") return parsed > 0;
  return false;
}
function buildEneaGeneratorPortalScript(mapped, includeTestValues = false) {
  const fieldsById = new Map(
    mapped.sections.flatMap((section2) => section2.fields).map((field) => [field.id, field])
  );
  const generatorLabel = fieldsById.get("impianto.generatore")?.value.trim() ?? "";
  const portalFields = generatorPortalFields(generatorLabel);
  const readyNumericFields = portalFields.flatMap((definition) => {
    const field = fieldsById.get(definition.fieldId);
    const usableOfficialValue = field?.status === "ready" && !field.testOnly;
    const usableTestValue = includeTestValues && Boolean(field?.value) && Boolean(field?.testOnly || field?.status === "review" || usableOfficialValue);
    if (!field || !usableOfficialValue && !usableTestValue) return [];
    const value = numericValue3(field.value);
    if (!value || !isValidGeneratorValue(definition.fieldId, value)) return [];
    const prepared = {
      portalId: definition.portalId,
      control: "input",
      value
    };
    return [{ ...definition, prepared }];
  });
  const usesOtherPortalRow = ["energia elettrica", "caldaia a gpl", "altro"].includes(generatorLabel.toLocaleLowerCase("it"));
  const readyFields = [
    ...readyNumericFields,
    ...usesOtherPortalRow && generatorLabel ? [{
      fieldId: "impianto.generatore",
      portalId: "id-altro",
      prepared: { portalId: "id-altro", control: "input", value: generatorLabel }
    }] : []
  ];
  const readyFieldIds = readyFields.map(({ fieldId }) => fieldId);
  const readySet = new Set(readyFieldIds);
  const skippedFieldIds = portalFields.map(({ fieldId }) => fieldId).filter((fieldId) => !readySet.has(fieldId));
  const runtime = {
    fields: readyFields.map(({ prepared }) => prepared),
    pageName: "Generatore dell'impianto termico",
    markerIds: portalFields.map(({ portalId }) => portalId),
    successMessage: "ENEA Lab: generatore compilato. Nessun salvataggio o invio eseguito.",
    activationLabel: generatorLabel,
    hostRoute: "impianto_esistente"
  };
  return {
    script: buildEneaPortalRuntimeScript(runtime),
    readyFieldIds,
    skippedFieldIds,
    runtime
  };
}

