// src/features/enea-lab/screeningRules.ts
var ENEA_SCREENING_TYPE = {
  awning: "Tenda o veneziana",
  persiana: "Persiana",
  rollerShutter: "Persiane avvolgibili",
  otherSolarScreening: "Altra schermatura solare"
};
var ENEA_SCREENING_INSTALLATION = {
  external: "Esterna"
};
var ENEA_SCREENING_CALCULATION = {
  supplierDeclared: "Dichiarato dal fornitore"
};
var ENEA_SCREENING_MATERIAL = {
  fabric: "Tessuto",
  pvc: "PVC",
  metal: "Metallo",
  mixed: "Misto"
};
var ENEA_SCREENING_REGULATION = {
  manual: "Manuale",
  automatic: "Automatico"
};
function normalize4(value) {
  return value.normalize("NFD").replace(/[\u0300-\u036f]/g, "").toLocaleLowerCase("it");
}
function screeningRules(declaredType, description, documentedGTot) {
  const normalized = normalize4(description);
  const classification = classifyScreeningProduct(description, declaredType);
  const zanzariera = classification.family === "zanzariera";
  const shutter = classification.family === "tapparella" || classification.family === "avvolgibile";
  const persiana = classification.family === "persiana";
  const pergotenda = declaredType === "pergotenda" || /pergotend/.test(normalized);
  const pergola = declaredType === "pergola" || /pergola/.test(normalized);
  const awning = declaredType === "tende_da_sole" || /tenda da sole|tende da sole|tenda a bracci/.test(normalized);
  const validDocumentedGTot = documentedGTot !== null && documentedGTot !== void 0 && documentedGTot > 0 && documentedGTot <= 0.35;
  const gTotResolution = resolveScreeningGTot(description, declaredType, documentedGTot);
  let material2 = "";
  if (persiana || shutter) material2 = ENEA_SCREENING_MATERIAL.metal;
  else if (zanzariera) material2 = ENEA_SCREENING_MATERIAL.mixed;
  else if (pergotenda) material2 = ENEA_SCREENING_MATERIAL.pvc;
  else if (pergola) material2 = ENEA_SCREENING_MATERIAL.metal;
  else if (/\bpvc\b/.test(normalized)) material2 = ENEA_SCREENING_MATERIAL.pvc;
  else if (/allumini|metall/.test(normalized)) material2 = ENEA_SCREENING_MATERIAL.metal;
  else if (awning) material2 = ENEA_SCREENING_MATERIAL.fabric;
  const describedMechanism = resolveScreeningMechanism(description);
  const explicitlyMotorized = describedMechanism.value === "automatico";
  const regulation = describedMechanism.value === "manuale" ? ENEA_SCREENING_REGULATION.manual : explicitlyMotorized ? ENEA_SCREENING_REGULATION.automatic : zanzariera ? ENEA_SCREENING_REGULATION.manual : pergotenda || pergola ? ENEA_SCREENING_REGULATION.automatic : awning || shutter || persiana ? ENEA_SCREENING_REGULATION.manual : "";
  return {
    type: persiana ? ENEA_SCREENING_TYPE.persiana : shutter ? ENEA_SCREENING_TYPE.rollerShutter : awning && !zanzariera && !shutter && !pergotenda && !pergola ? ENEA_SCREENING_TYPE.awning : declaredType || zanzariera || shutter || pergotenda || pergola ? ENEA_SCREENING_TYPE.otherSolarScreening : "",
    installation: declaredType || description.trim() ? ENEA_SCREENING_INSTALLATION.external : "",
    gTot: gTotResolution.value,
    gTotFromDocument: validDocumentedGTot,
    gTotResolutionStatus: gTotResolution.source === "operator_required" ? "operator_required" : "resolved",
    gTotRuleId: gTotResolution.ruleId,
    calculation: declaredType || description.trim() ? ENEA_SCREENING_CALCULATION.supplierDeclared : "",
    material: material2,
    regulation,
    regulationConflict: describedMechanism.conflict,
    supplementaryThermalResistance: persiana || shutter ? 0.17 : null
  };
}

